import { gsap } from 'gsap';
import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, varying } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // STAGE BACKDROP: vertical gradient from config colors
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  const gradientStops = config.intent?.visualSpec?.colors?.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.6, hex: '#12121a' },
    { at: 1, hex: '#16161d' }
  ];

  // Build gradient via TSL: v.y from -1 (bottom) to +1 (top)
  const vUv = varying(uv());
  const gradCol = uniform(new THREE.Vector3(0.067, 0.067, 0.063)); // #0b0b10
  const mid = uniform(new THREE.Vector3(0.071, 0.071, 0.102)); // #12121a
  const top = uniform(new THREE.Vector3(0.086, 0.086, 0.114)); // #16161d

  const yNorm = smoothstep(0, 1, vUv.y);
  const colNode = mix(gradCol, mid, smoothstep(0, 0.6, yNorm)).mix(top, smoothstep(0.6, 1, yNorm));

  backdropMat.colorNode = colNode;
  backdropMat.emissiveIntensity = 0;

  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // LIGHTING SETUP
  // Key light: 1.2 intensity at 30-45 deg
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(1.5, 2.0, 1.8);
  keyLight.castShadow = true;
  group.add(keyLight);

  // Back/rim light: cool directional from behind-left, 0.9 intensity
  const rimLight = new THREE.DirectionalLight(0xa8bfd4, 0.9); // cool white-blue
  rimLight.position.set(-1.8, 1.2, -2.0);
  group.add(rimLight);

  // Ambient fill: 0.6 intensity (scene default, but reinforce locally)
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
  group.add(ambientLight);

  // PRISM: equilateral triangular prism
  // Cross-section: 1.2 units per side; length: 1.8 units along x-axis
  // Rotated 12 deg on z, 20 deg on y
  const prismGroup = new THREE.Group();

  // Create triangular prism manually: 2 triangles (front/back) + 3 rectangular sides
  const prismGeom = new THREE.BufferGeometry();
  const sideLen = 1.2;
  const prismLen = 1.8;
  const h = (sideLen * Math.sqrt(3)) / 2; // height of equilateral triangle

  // Equilateral triangle vertices (centered at origin in xy plane)
  const triVerts = [
    new THREE.Vector3(0, h * (2 / 3), 0),       // top
    new THREE.Vector3(-sideLen / 2, -h / 3, 0), // bottom-left
    new THREE.Vector3(sideLen / 2, -h / 3, 0)   // bottom-right
  ];

  const verts = [];
  const indices = [];

  // Front face triangle (z = -prismLen/2)
  const z0 = -prismLen / 2;
  verts.push(...triVerts[0].toArray(), z0);
  verts.push(...triVerts[1].toArray(), z0);
  verts.push(...triVerts[2].toArray(), z0);

  // Back face triangle (z = +prismLen/2)
  const z1 = prismLen / 2;
  verts.push(...triVerts[0].toArray(), z1);
  verts.push(...triVerts[1].toArray(), z1);
  verts.push(...triVerts[2].toArray(), z1);

  // Front triangle indices
  indices.push(0, 1, 2);
  // Back triangle indices (reversed winding)
  indices.push(5, 4, 3);

  // Side 0: top-left edge (vertices 0,1,3,4)
  indices.push(0, 3, 4, 0, 4, 1);
  // Side 1: top-right edge (vertices 0,2,3,5)
  indices.push(0, 2, 5, 0, 5, 3);
  // Side 2: bottom edge (vertices 1,2,4,5)
  indices.push(1, 4, 5, 1, 5, 2);

  prismGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(verts), 3));
  prismGeom.setIndex(new THREE.BufferAttribute(new Uint32Array(indices), 1));
  prismGeom.computeVertexNormals();

  // PRISM MATERIAL: MeshPhysicalNodeMaterial with transmission, iridescence, clearcoat
  const prismMat = new MeshPhysicalNodeMaterial();
  prismMat.transmission = 1.0;
  prismMat.thickness = 0.9;
  prismMat.ior = 1.55;
  prismMat.roughness = 0.08;
  prismMat.clearcoat = 0.25;
  prismMat.clearcoatRoughness = 0.1;

  // Iridescence
  prismMat.iridescence = 1.0;
  prismMat.iridescenceIOR = 1.3;
  prismMat.iridescenceThicknessRange = [120, 480];

  // Attenuation: color #e8ecf2, distance 2.5
  prismMat.attenuationColor = new THREE.Color('#e8ecf2');
  prismMat.attenuationDistance = 2.5;

  // Base color (nearly transparent, faint paper hue)
  prismMat.color = new THREE.Color('#e8ecf2');
  prismMat.opacity = 0.92;
  prismMat.transparent = true;

  // Dispersion via roughness modulation (approximation for TSL; full dispersive splitting
  // is achieved via iridescence + ior in WebGPU backend)

  const prism = new THREE.Mesh(prismGeom, prismMat);
  prism.rotation.z = THREE.MathUtils.degToRad(12);
  prism.rotation.y = THREE.MathUtils.degToRad(20);
  prismGroup.add(prism);

  // EMISSIVE CORE: 0.35-unit octahedron inside prism
  const coreGeom = new THREE.OctahedronGeometry(0.35, 3);
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color = new THREE.Color('#ff2a38');
  coreMat.emissive = new THREE.Color('#ff2a38');
  coreMat.emissiveIntensity = 2.2;
  coreMat.metalness = 0.0;
  coreMat.roughness = 0.3;

  const core = new THREE.Mesh(coreGeom, coreMat);
  core.castShadow = true;
  prismGroup.add(core);

  // Position prism group at origin
  prismGroup.position.set(0, 0.2, 0);
  group.add(prismGroup);

  // CAUSTIC STREAK: 2.4 x 0.5 plane on floor with dispersed gradient
  const causticGeom = new THREE.PlaneGeometry(2.4, 0.5);
  const causticMat = new MeshStandardNodeMaterial();

  // Engineered linear gradient: #ff2a38 at 0.2, #e8ecf2 at 0.5, #9fb0c4 at 0.8
  const col1 = uniform(new THREE.Vector3(1.0, 0.165, 0.22)); // #ff2a38
  const col2 = uniform(new THREE.Vector3(0.91, 0.925, 0.949)); // #e8ecf2
  const col3 = uniform(new THREE.Vector3(0.624, 0.69, 0.768)); // #9fb0c4

  const causticUv = varying(uv());
  const causticGrad = mix(
    col1,
    col2,
    smoothstep(0.0, 0.5, causticUv.x)
  ).mix(col3, smoothstep(0.5, 1.0, causticUv.x));

  causticMat.colorNode = causticGrad;
  causticMat.emissiveIntensity = 0;
  causticMat.transparent = true;
  causticMat.opacity = 0.35;
  causticMat.side = THREE.DoubleSide;

  const caustic = new THREE.Mesh(causticGeom, causticMat);
  caustic.position.set(0, -1.1, -0.1);
  caustic.rotation.x = THREE.MathUtils.degToRad(-90);
  caustic.scale.x = 1.0; // will animate
  group.add(caustic);

  // TEXT: "Light, machined." (headline)
  const headlineText = ctx.fontAtlas.createText('Light, machined.', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: -0.34
  });
  headlineText.position.set(0, -1.75, 0.5);
  group.add(headlineText);

  // TEXT: "SAPPHIRE OVER DIAL / ZERO DISTORTION" (caption)
  const captionText = ctx.fontAtlas.createText('SAPPHIRE OVER DIAL / ZERO DISTORTION', {
    fontSize: 18,
    color: '#a8bfd4',
    align: 'center',
    letterSpacingPx: 1.44
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // INTERACTION: depth-rotate on hover
  let rotTimeline = null;
  const cleanup = () => {
    if (rotTimeline) rotTimeline.kill();
  };

  const onHoverStart = (evt) => {
    if (rotTimeline) rotTimeline.kill();
    const mouseX = evt.clientX / window.innerWidth;
    const mouseY = evt.clientY / window.innerHeight;
    const targetRotX = (mouseY - 0.5) * THREE.MathUtils.degToRad(10);
    const targetRotY = (mouseX - 0.5) * THREE.MathUtils.degToRad(10);

    rotTimeline = gsap.to(prismGroup.rotation, {
      x: targetRotX,
      y: prismGroup.rotation.y + targetRotY,
      duration: 0.35,
      ease: 'cubic-bezier(0.215,0.61,0.355,1)'
    });

    // Caustic elongation
    gsap.to(caustic.scale, {
      x: 1.08,
      duration: 0.35,
      ease: 'power2.out'
    });
  };

  const onHoverEnd = () => {
    if (rotTimeline) rotTimeline.kill();
    rotTimeline = gsap.to(prismGroup.rotation, {
      x: 0,
      y: THREE.MathUtils.degToRad(20),
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      overwrite: false
    });

    gsap.to(caustic.scale, {
      x: 1.0,
      duration: 0.9,
      ease: 'power4.out'
    });
  };

  group.userData = {
    handlers: {
      'hover:start': onHoverStart,
      'hover:end': onHoverEnd
    },
    cleanup: cleanup
  };

  return group;
}
